// OTHVM Android - agent tool proxy to the Android agent via laptop MCP.
const input = $json || {};
const payload = {};
for (const [k, v] of Object.entries(input)) {
  if (k === 'params' || k === 'operation' || k === 'category') continue;
  if (v === undefined || v === null) continue;
  payload[k] = v;
}
payload.action = String(input.action || 'status');
try {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://127.0.0.1:8765/tools/android',
    headers: { 'Content-Type': 'application/json', 'X-API-Key': 'REPLACE_WITH_MCP_API_KEY' },
    body: payload,
    json: true,
    timeout: 60000
  });
  return [{ json: r }];
} catch (e) {
  return [{ json: { ok: false, error: String((e && e.message) || e) } }];
}

// OTHVM — expand params; keep flat args and normalize action/operation.
const j = $json || {};
let p = j.params;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { p = {}; } }
if (!p || typeof p !== 'object' || Array.isArray(p)) p = {};
const out = {};
for (const [k, v] of Object.entries(j)) {
  if (k === 'params') continue;
  out[k] = v;
}
Object.assign(out, p);
if (out.action === undefined && out.operation !== undefined) out.action = out.operation;
if (out.operation === undefined && out.action !== undefined) out.operation = out.action;
return [{ json: out }];
